css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .bulb { position: absolute; left: 36%; top: 4%; width: 28%; height: 26%; border-radius: 46% 46% 34% 34%; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 50% 100%; animation: pip-squeeze calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .stem { position: absolute; left: 45%; top: 28%; width: 10%; height: 34%; background: color-mix(in srgb, var(--accent-2) 55%, transparent); clip-path: polygon(0 0, 100% 0, 66% 100%, 34% 100%); }
.loader i { position: absolute; left: 45%; top: 60%; width: 10%; height: 12%; border-radius: 50% 50% 50% 50% / 66% 66% 34% 34%; background: var(--accent); opacity: 0; animation: pip-fall calc(var(--loader-speed) * 1.6) ease-in infinite; }
.loader i:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * .8); }
.loader .well { position: absolute; left: 22%; right: 22%; bottom: 6%; height: 18%; border-radius: 4px 4px 40% 40%; background: color-mix(in srgb, var(--accent) 22%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent); animation: pip-ripple calc(var(--loader-speed) * 1.6) ease-out infinite; }
@keyframes pip-squeeze { 0%, 30% { transform: scale(1); } 46% { transform: scale(.76, .84); } 66%, 100% { transform: scale(1); } }
@keyframes pip-fall { 0%, 44% { opacity: 0; transform: translateY(0) scale(.5); } 52% { opacity: 1; transform: translateY(0) scale(1); } 94%, 100% { opacity: 0; transform: translateY(170%) scale(.7); } }
@keyframes pip-ripple { 0%, 88% { transform: scaleX(1); } 94% { transform: scaleX(1.06); } 100% { transform: scaleX(1); } }
